from sheet import evaluate
from sheet.engine import CycleError

assert evaluate({"A": "=-3"})["A"] == -3.0
assert evaluate({"A": "1", "B": "=-(A+1)"})["B"] == -2.0
assert evaluate({"A": "=3/2"})["A"] == 1.5
assert evaluate({"A": "= ( 1 + 2 ) * X12", "X12": "3.5"})["A"] == 10.5
assert evaluate({"TOTAL": "=A - B - C", "A": "10", "B": "3", "C": "2"})["TOTAL"] == 5.0

try:
    evaluate({"A": "=1/0"})
except ZeroDivisionError:
    pass
else:
    raise AssertionError("expected ZeroDivisionError")

try:
    evaluate({"A": "=B", "B": "=A"})
except CycleError:
    pass
else:
    raise AssertionError("expected CycleError")

try:
    evaluate({"A": "=A"})
except CycleError:
    pass
else:
    raise AssertionError("expected CycleError")

print("all edge cases ok")
